using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Prove it works — round-trip serialize using the typed info.
var person = new Person("Alice", 30);
string json = JsonSerializer.Serialize(person, personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing — TryGetTypeInfo returns false when
//    metadata isn't available (e.g. for a type not supported by the resolver).
//    Here we use a resolver that only handles Person, so int[] will fail.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"TryGet succeeded for Person: {found!.Type.Name}");
else
    Console.WriteLine("TryGet failed for Person (unexpected)");

if (limited.TryGetTypeInfo(typeof(int[]), out _))
    Console.WriteLine("TryGet succeeded for int[] (unexpected)");
else
    Console.WriteLine("TryGet correctly returned false for int[] — no exception thrown.");

// --- Supporting types ---

public record Person(string Name, int Age);

/// <summary>A resolver that only provides metadata for Person.</summary>
file sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) =>
        type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}

